import sys
import random
input = sys.stdin.read

def main():
    data = input().split()
    n = int(data[0])
    ratings = list(map(int, data[1:]))

    ratings.sort()

    for i in range(1, 2*n):
        if ratings[i] == ratings[i-1]:
            if random.choice([True, False]):
                ratings[i], ratings[i-1] = ratings[i-1], ratings[i]

    team1 = ratings[:n]
    team2 = ratings[n:]

